def maxTreeDepth(tree: list) -> int:
    if not tree or tree[0] is None:
        return 0
    # Convert level-order array into depth
    # Node at index i has children 2*i + 1 and 2*i + 2
    def dfs(idx):
        if idx >= len(tree) or tree[idx] is None:
            return 0
        return 1 + max(dfs(2 * idx + 1), dfs(2 * idx + 2))
    return dfs(0)

